pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 extra) public {
        vm.assume(amount > 0);
        bound(amount, 1, 1e30);
        bound(extra, 0, 1e30);

        attacker = new Attacker(c);
        vm.deal(address(this), amount);
        attacker.deposit{value: amount}();
        uint256 recorded = c.getBalance(address(attacker));
        // extra funds so the contract COULD pay a (illegitimate) second payout
        vm.deal(address(c), extra);

        bool ok;
        try attacker.attack() { ok = true; } catch { ok = false; }

        // RULE: a withdrawal that completes successfully transfers exactly the
        // recorded balance of the caller — never more. If it cannot, it must
        // revert entirely.
        assertTrue(!ok || attacker.received() == recorded, "successful withdrawal must pay exactly the recorded balance");
    }
}

contract Attacker {
    C c;
    uint256 totalReceived;
    bool reentered;

    constructor(C _c) { c = _c; }

    function deposit() external payable {
        c.addToBalance{value: msg.value}();
    }

    function attack() external returns (bool) {
        reentered = false;
        uint256 before = address(this).balance;
        c.withdrawBalance();
        totalReceived += address(this).balance - before;
        return true;
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            c.withdrawBalance();
        }
    }

    function received() external view returns (uint256) {
        return totalReceived;
    }
}

